                raise RecoveryError(
                    "restore backup contains an illegal path"
                ) from exc
            if not _is_whitelisted(wallet_id, rel):
                raise RecoveryError(
                    "restore backup contains a non-whitelisted path"
                )
            found.append(rel)
    return found


